mapper.select:
 select lt.total_days as totalAvailableDay,coalesce(sum(datediff(lr.end_date,lr.start_date)+1),0) as usedLeave,
    (lt.total_days - coalesce(sum(datediff(lr.end_date,lr.start_date)+1),0)) as remainingDay
from leave_type lt left join leave_request lr on lr.leave_type_id = lt.id and lr.status="APPROVED" and lr.employee_id=#{employeeId}  where  lt.name = "casual leave" group by lt.id;

